\node[anchor=west] at (axis cs:1.05,0.15) {\((1,0)\)};
\node[anchor=west] at (axis cs:0.25,2.65) {\(p(x)=x^4-3x^2+2\)};
\node[anchor=west] at (axis cs:0.8,-0.9) {tangent slope \(-2\)};
